package com.mycompany.rentalmanagement.servlet;
import com.mycompany.rentalmanagement.dao.VehicleDAO;import com.mycompany.rentalmanagement.util.ValidationUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.math.BigDecimal;
@WebServlet("/vehicles") public class VehicleServlet extends HttpServlet{VehicleDAO dao=new VehicleDAO();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String action=r.getParameter("action");if("edit".equals(action)){r.setAttribute("vehicle",dao.get(Long.parseLong(r.getParameter("id"))));r.getRequestDispatcher("/WEB-INF/views/vehicle-form.jsp").forward(r,s);return;}r.setAttribute("vehicles",dao.list(r.getParameter("q")));r.getRequestDispatcher("/WEB-INF/views/vehicles.jsp").forward(r,s);}catch(Exception e){r.setAttribute("error",e.getMessage());r.getRequestDispatcher("/WEB-INF/views/error.jsp").forward(r,s);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String action=r.getParameter("action");if("deactivate".equals(action))dao.deactivate(Long.parseLong(r.getParameter("id")));else{long id=r.getParameter("id")==null||r.getParameter("id").isBlank()?0:Long.parseLong(r.getParameter("id"));String reg=ValidationUtil.text(r.getParameter("registration_number"),"Registration number",30).toUpperCase();String make=ValidationUtil.text(r.getParameter("make"),"Make",80);String model=ValidationUtil.text(r.getParameter("model"),"Model",80);String type=ValidationUtil.text(r.getParameter("vehicle_type"),"Type",50);int year=Integer.parseInt(r.getParameter("model_year"));if(year<1950||year>2100)throw new IllegalArgumentException("Model year must be between 1950 and 2100.");BigDecimal rate=ValidationUtil.money(r.getParameter("daily_rate"),"Daily rate");String status=r.getParameter("status");if(!java.util.Set.of("AVAILABLE","RENTED","MAINTENANCE","INACTIVE").contains(status))throw new IllegalArgumentException("Invalid vehicle status.");dao.save(id,reg,make,model,type,year,rate,status,r.getParameter("notes"));}s.sendRedirect(r.getContextPath()+"/vehicles?success=1");}catch(Exception e){r.setAttribute("error",e.getMessage());try{r.setAttribute("vehicles",dao.list(""));}catch(Exception ignored){}r.getRequestDispatcher("/WEB-INF/views/vehicles.jsp").forward(r,s);}}}
